'use strict';

// MODULES //

var basename = require( 'path' ).basename;
var resolve = require( 'path' ).resolve;
var path = require( 'path' );
var ls = require( '@stdlib/_tools/pkgs/names' ).sync;
var findPkgs = require( '@stdlib/_tools/pkgs/find' ).sync;
var rootDir = require( '@stdlib/_tools/utils/root-dir' );
var readJSON = require( '@stdlib/fs/read-json' ).sync;
var pkg = require( './.././package.json' );


// VARIABLES //

var pathString = '@stdlib/math/base/special';
var basePkg = basename( pkg.name );
var ROOT_DIR = rootDir();
var opts = {
	'dir': './' + pathString
};
var jsonOpts = {
	'encoding': 'utf8'
};


// FUNCTIONS //

/**
* Returns a list of packages in `math/base/special/*` which are relevant for the current package.
*
* ## Note
*
* For now, we are trying the following four combinations. So, let us say, we are looking for the `sin` package, then we will try to find:
*
* -   `@stdlib/math/base/special/sinf`
* -   `@stdlib/math/base/special/sin`
* -   `@stdlib/math/base/special/csinf`
* -   `@stdlib/math/base/special/csin`
*
* Now since as of now, we don't have `@stdlib/math/base/special/csin` and `@stdlib/math/base/special/csinf`, we will only get the first two packages.
*
* @private
* @returns {Array} list of relevant packages
*
* @example
* var basePkg = 'inv';
*
* var pkgs = getRelevantPackages();
* // returns [ '@stdlib/math/base/special/invf', '@stdlib/math/base/special/inv', '@stdlib/math/base/special/cinvf', '@stdlib/math/base/special/cinv' ]
*
* @example
* var basePkg = 'sin';
*
* var pkgs = getRelevantPackages( 'sin' );
* // returns [ '@stdlib/math/base/special/sinf', '@stdlib/math/base/special/sin' ]
*/
function getRelevantPackages() {
	var combinations;
	var names;
	var pkgs;
	var pkg;
	var i;
	var j;

	pkgs = [];

	// Initializing all possible combinations that we can try, in the required order:
	combinations = [
		path.join( pathString, basePkg + 'f' ),
		path.join( pathString, basePkg ),
		path.join( pathString, 'c' + basePkg + 'f' ),
		path.join( pathString, 'c' + basePkg )
	];

	// Get the list of all packages in `math/base/special/*`:
	names = ls( opts );

	// Filter the list of packages to only include those which match the combinations:
	for ( i = 0; i < combinations.length; i++ ) {
		pkg = combinations[ i ];
		for ( j = 0; j < names.length; j++ ) {
			if ( names[ j ] === pkg ) {
				pkgs.push( pkg );
			}
		}
	}

	return pkgs;
}

/**
* Returns the input and output dtypes for a given package.
*
* ## Note
*
* -   Currently, this function only supports those packages which expect a single input and return a single output.
* -   In order to support packages with multiple inputs, we'll need to restructure our table and calculate accordingly.
* -   As of now, each array in our table looks like this:
*
* [ input_dtype, output_dtype, package_name ]
* For example: [ 'float32', 'float32', '@stdlib/math/base/special/sinf' ]
*
* This is fine for single input & single output functions. But, for functions such as `pow`, which expect two input values, we can have:
*
* [ number_of_inputs, input_dtype_1, input_dtype_2, ... input_dtype_n, output_dtype, package_name ]
* [ 2, 'float64', 'float64', `float64`, '@stdlib/math/base/special/pow' ]
*
* @private
* @param {string} alias - package name
* @returns {Array} input and output dtypes
*
* @example
* var dtypes = getDtypes( 'acos' );
* // returns [ 'float64', 'float64' ]
*
* @example
* var dtypes = getDtypes( 'acosf' );
* // returns [ 'float32', 'float32' ]
*/
function getDtypes( alias ) {
	var outputDtype;
	var inputDtype;
	var path;
	var json;
	var pkg;
	var out;
	var o;

	// Resolve the package:
	pkg = findPkgs({
		'dir': ROOT_DIR,
		'pattern': '**/math/base/special/'+ alias +'/package.json'
	});

	if ( pkg.length === 0 ) {
		return [];
	}

	// Get the meta data:
	path = resolve( ROOT_DIR, pkg[ 0 ] );
	json = readJSON( resolve( path, 'package.json' ), jsonOpts );
	o = json.__stdlib__; // eslint-disable-line no-underscore-dangle
	if ( o && o.scaffold && o.scaffold.parameters.length >= 1 ) {
		out = o.scaffold;
	}

	// NOTE: We might need to reconsider the below logic if there are two or more inputs...
	inputDtype = out.parameters[ 0 ].type.dtype;
	outputDtype = out.returns.type.dtype;

	return [ inputDtype, outputDtype ];
}


// MAIN //

/**
* Generate the function table.
*
* @returns {Array} function table
*
* @example
* var basePkg = 'ceil';
*
* var table = generateTable();
* // returns [ [ 'float32', 'float32', '@stdlib/math/base/special/ceilf' ], [ 'float64', 'float64', '@stdlib/math/base/special/ceil' ], [ 'complex64', 'complex64', '@stdlib/math/base/special/cceilf' ], [ 'complex128', 'complex128', '@stdlib/math/base/special/cceil' ] ]
*/
function generateTable() {
	var aliasName;
	var dtypes;
	var table;
	var pkgs;
	var pkg;
	var i;

	// Get the list of relevant packages for the given base package:
	pkgs = getRelevantPackages();

	// Initialize the table:
	table = [];

	// Loop over the packages and get the input and output dtypes:
	for ( i = 0; i < pkgs.length; i++ ) {
		// Extract the alias name out of the package path:
		pkg = pkgs[ i ];
		aliasName = pkg.replace( pathString + '/', '' );
		dtypes = getDtypes( aliasName );
		table.push( [ dtypes[ 0 ], dtypes[ 1 ], pkg ] );
	}

	return table;
}


// EXPORTS //

module.exports = generateTable;
